-- Seed: copies frontend/assets/catalogue.json into Supabase (upsert, safe to re-run).
begin;
insert into public.categories (id,name,description,sort)
select id,name,description,sort from jsonb_to_recordset($j$[{"id": "canapes", "name": "Canapés", "description": "Le confort dans toutes ses expressions.", "sort": 0}, {"id": "fauteuils", "name": "Fauteuils", "description": "Des lignes singulières pour chaque espace.", "sort": 1}, {"id": "tables", "name": "Tables", "description": "La rencontre de la matière et du dessin.", "sort": 2}, {"id": "chambres", "name": "Chambres", "description": "Le repos comme un art de vivre.", "sort": 3}, {"id": "coussins", "name": "Coussins", "description": "Textiles et confort réalisés sur mesure.", "sort": 4}, {"id": "chaises", "name": "Chaises", "description": "L’assise réinventée.", "sort": 5}, {"id": "rangements", "name": "Rangements", "description": "L’équilibre entre élégance et fonction.", "sort": 6}, {"id": "decoration", "name": "Décoration", "description": "Des détails qui donnent du caractère.", "sort": 7}, {"id": "exterieur", "name": "Extérieur", "description": "La maison se prolonge dehors.", "sort": 8}, {"id": "cuisines", "name": "Cuisines", "description": "Des cuisines sur mesure, pensées au millimètre pour votre intérieur.", "sort": 9}]$j$::jsonb) as x(id text,name text,description text,sort int)
on conflict (id) do update set name=excluded.name, description=excluded.description, sort=excluded.sort;
insert into public.colors (name,hex,sort)
select name,hex,sort from jsonb_to_recordset($j$[{"hex": "#E5DFD3", "name": "Ivoire", "sort": 0}, {"hex": "#AB7B56", "name": "Cognac", "sort": 1}, {"hex": "#68635C", "name": "Taupe", "sort": 2}, {"hex": "#535B4C", "name": "Sauge", "sort": 3}, {"hex": "#343537", "name": "Charbon", "sort": 4}, {"hex": "#C5AC90", "name": "Sable", "sort": 5}]$j$::jsonb) as x(name text,hex text,sort int)
on conflict (name) do update set hex=excluded.hex, sort=excluded.sort;
insert into public.products (id,slug,name,category,description,price,sku,material,dimensions,color,image,fallback,gallery,featured,is_new,sort)
overriding system value
