on conflict (slug) do update set name=excluded.name, category=excluded.category, description=excluded.description, price=excluded.price, sku=excluded.sku,
  material=excluded.material, dimensions=excluded.dimensions, color=excluded.color, image=excluded.image, fallback=excluded.fallback, gallery=excluded.gallery,
  featured=excluded.featured, is_new=excluded.is_new, sort=excluded.sort;
select setval(pg_get_serial_sequence('public.products','id'), (select max(id) from public.products));
commit;
